    },
    "N018_retry_b": {
      "speakerName": "@s",
      "dialogueContent": "오답입니다. 성인의 정확한 가슴 압박 위치는 흉골 하부 1/2 지점입니다.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": false,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
