    "D008": {
      "speakerName": "@s",
      "dialogueContent": "AVPU 중 P이며, GCS는 E2 / V2 / M4로 총 8점입니다.",
      "dialogueContentTTSPassing": "에이 브이 피 유 중 피이며, 지 씨 에스는 이 투, 브이 투, 엠 포로 총 8점입니다.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": true,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
        "preset": "F4"
      },
      "identifier": "D008",
      "nodeType": "Dialogue",
      "nextIdentifier": "Q008_1"
    },
    "D009": {
      "speakerName": "@s",
      "dialogueContent": "경추 고정, 구강 흡인 완료했습니다.",
