    },
    "D017": {
      "speakerName": "@s",
      "dialogueContent": "지혈 중입니다. 거즈 고정했습니다.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": true,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
        "preset": "F4"
      },
      "identifier": "D017",
      "nodeType": "Dialogue",
      "nextIdentifier": "Q012_1"
    },
    "D018": {
      "speakerName": "@s",
      "dialogueContent": "양측 정맥로가 모두 확보되었습니다.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": true,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
        "preset": "F5"
