    },
    "D019": {
      "speakerName": "의사",
      "dialogueContent": "그래도 혈압이 잡히지 않네요. C-line 잡아서 수액을 빠르게 투여하겠습니다. @t=[nurse_c, @s]선생님, C-line set 건네주세요.",
      "dialogueContentTTSPassing": "그래도 혈압이 잡히지 않네요. 씨 라인 잡아서 수액을 빠르게 투여하겠습니다. @t=[nurse_c, @s]선생님, 씨 라인 세트 건네주세요.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": true,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
        "preset": "M2"
      },
      "identifier": "D019",
      "nodeType": "Dialogue",
      "nextIdentifier": "Q014"
    },
    "D020": {
      "speakerName": "의사",
      "dialogueContent": "@t=[nurse_c, @s]선생님, Level 1 rapid infuser에 플라즈마 솔루션과 혈액백 연결시켜주세요.",
      "dialogueContentTTSPassing": "@t=[nurse_c, @s]선생님, 레벨 원 래피드 인퓨저에 플라즈마 솔루션과 혈액백 연결시켜 주세요.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": true,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
        "preset": "M2"
      },
      "identifier": "D020",
      "nodeType": "Dialogue",
      "nextIdentifier": "Q015"
    },
    "D021": {
      "speakerName": "@s",
      "dialogueContent": "Level 1에 플라즈마 솔루션과 혈액백을 연결하고, 환자의 C-line에도 연결했습니다.",
      "dialogueContentTTSPassing": "레벨 원에 플라즈마 솔루션과 혈액백을 연결하고, 환자의 씨 라인에도 연결했습니다.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": true,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
        "preset": "F4"
      },
      "identifier": "D021",
      "nodeType": "Dialogue",
      "nextIdentifier": "Q015_1"
    },
    "D022": {
      "speakerName": "의사",
      "dialogueContent": "그래도 혈압이 잘 안잡히네요...",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": true,
