    },
    "N018_retry_c": {
      "speakerName": "@s",
      "dialogueContent": "오답입니다. 정확한 가슴 압박 횟수는 분당 약 100~120회 입니다.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
