    },
    "N019_retry_a": {
      "speakerName": "@s",
      "dialogueContent": "오답입니다. 제시된 심전도 중 제세동이 필요한 심전도는 VF(심실세동) 입니다.",
      "portraitSpriteIdentifier": null,
      "autoAdvanceSeconds": null,
      "interactionRequired": null,
      "playTTS": false,
      "ttsVoiceIdentifier": null,
      "ttsVoiceProfile": {
        "preset": "F3"
      },
