      "nodeType": "Dialogue",
      "nextIdentifier": "C016"
    },
    "N019_retry_b": {
      "speakerName": "@s",
      "dialogueContent": "오답입니다. 이상파형 제세동기는 150~200J(줄)이면 충분합니다.",
